import {Config} from '@remotion/cli/config';

// Inputs (voice, score, timeline.json) are generated by build.mjs into build/<film>/public, which every remotion call
// names with --public-dir; build/public is only the fallback for a bare `remotion studio`.
Config.setPublicDir('build/public');
Config.setVideoImageFormat('png');
Config.setPixelFormat('yuv420p');
Config.setCodec('h264');
Config.setCrf(14);
Config.setColorSpace('bt709');
